mod_controls_server <- function(id, is_admin = NULL, shared_admin = NULL, reset_signal = NULL, borough_names = NULL) {
  shiny::moduleServer(id, function(input, output, session) {
    ns <- session$ns
    if (is.null(is_admin)) {
      is_admin <- function() FALSE
    }

    scenario_defs <- scenario_catalog()
    default_scenario <- scenario_lookup("custom", scenario_defs)
    default_death_ifr <- 0.002
    default_death_delay <- 4L
    admin_defaults <- list(
      Rt = default_scenario$Rt[[1]],
      k = default_scenario$k[[1]],
      imports_prob = default_scenario$imports_prob[[1]],
      lambda_import = default_scenario$lambda_import[[1]],
      seed_borough = default_scenario$seed_borough[[1]],
      seed_cases = default_scenario$seed_cases[[1]],
      kernel_key = default_scenario$kernel_key[[1]],
      susceptible_frac = default_scenario$susceptible_frac[[1]],
      scenario_id = default_scenario$id[[1]],
      death_ifr = default_death_ifr,
      death_delay = default_death_delay
    )

    if (is.null(shared_admin)) {
      shared_admin <- shiny::reactiveValues(
        Rt = admin_defaults$Rt,
        k = admin_defaults$k,
        imports_prob = admin_defaults$imports_prob,
        lambda_import = admin_defaults$lambda_import,
        seed_borough = admin_defaults$seed_borough,
        seed_cases = admin_defaults$seed_cases,
        kernel_key = admin_defaults$kernel_key,
        susceptible_frac = admin_defaults$susceptible_frac,
        scenario_id = admin_defaults$scenario_id,
        death_ifr = admin_defaults$death_ifr,
        death_delay = admin_defaults$death_delay
      )
    }

    if (is.null(reset_signal)) {
      reset_signal <- shiny::reactiveVal(0L)
    }

    seed_choices <- c("Random" = "random")
    if (!is.null(borough_names) && length(borough_names) > 0) {
      seed_choices <- c(seed_choices, stats::setNames(seq_along(borough_names), borough_names))
    }
    scenario_labels <- scenario_choices(scenario_defs)

    seed_choice_from_value <- function(seed_value) {
      if (is.null(seed_value) || is.na(seed_value)) {
        "random"
      } else {
        as.character(seed_value)
      }
    }

    apply_scenario_defaults <- function(scenario_id) {
      scenario <- scenario_lookup(scenario_id, scenario_defs)
      death_ifr <- scenario$death_ifr[[1]]
      if (is.null(death_ifr) || is.na(death_ifr)) {
        death_ifr <- shared_admin$death_ifr
      }
      death_ifr <- min(1, max(0, death_ifr))
      # scenario delays are in days; the admin setting is in reports
      death_delay <- scenario$death_delay_days[[1]] / teaching_params()$report_days
      if (is.null(death_delay) || is.na(death_delay)) {
        death_delay <- shared_admin$death_delay
      }
      death_delay <- as.integer(round(death_delay))
      if (is.na(death_delay) || death_delay < 0L) {
        death_delay <- 0L
      }

      shared_admin$Rt <- scenario$Rt[[1]]
      shared_admin$k <- scenario$k[[1]]
      shared_admin$imports_prob <- scenario$imports_prob[[1]]
      shared_admin$lambda_import <- scenario$lambda_import[[1]]
      shared_admin$seed_borough <- scenario$seed_borough[[1]]
      shared_admin$seed_cases <- scenario$seed_cases[[1]]
      shared_admin$kernel_key <- scenario$kernel_key[[1]]
      shared_admin$susceptible_frac <- scenario$susceptible_frac[[1]]
      shared_admin$scenario_id <- scenario$id[[1]]
      shared_admin$death_ifr <- death_ifr
      shared_admin$death_delay <- death_delay

      shiny::updateNumericInput(
        session,
        "admin_rt",
        value = scenario$Rt[[1]]
      )
      shiny::updateNumericInput(
        session,
        "admin_k",
        value = scenario$k[[1]]
      )
      shiny::updateNumericInput(
        session,
        "admin_imports_prob",
        value = scenario$imports_prob[[1]]
      )
      shiny::updateNumericInput(
        session,
        "admin_lambda_import",
        value = scenario$lambda_import[[1]]
      )
      shiny::updateSelectInput(
        session,
        "admin_seed_borough",
        selected = seed_choice_from_value(scenario$seed_borough[[1]])
      )
      shiny::updateNumericInput(
        session,
        "admin_seed_cases",
        value = scenario$seed_cases[[1]]
      )
      shiny::updateNumericInput(
        session,
        "admin_death_ifr",
        value = death_ifr
      )
      shiny::updateNumericInput(
        session,
        "admin_death_delay",
        value = death_delay
      )
    }

    # Fixed parameters - students focus on testing strategy, not epidemiology.
    # Values come from teaching_params() so they can be tuned in one place.
    tp <- teaching_params()
    fixed_params <- list(
      testing = list(
        sens = tp$tests$sens,
        spec = tp$tests$spec,
        delays = tp$tests$delays,
        prev_floor = tp$tests$prev_floor
      ),
      budget = list(
        budget = tp$tests$budget,
        costs = tp$tests$costs
      ),
      starter_intel = "alert"
    )

    params_epidemic <- shiny::reactive({
      list(
        Rt = shared_admin$Rt,
        k = shared_admin$k,
        imports_prob = shared_admin$imports_prob,
        lambda_import = shared_admin$lambda_import
      )
    })

    params_mortality <- shiny::reactive({
      list(
        death_ifr = shared_admin$death_ifr,
        death_delay = shared_admin$death_delay
      )
    })

    params_testing <- shiny::reactive({
      testing <- fixed_params$testing
      # who to test is now chosen in the testing plan on the map card
      testing$sampling_mode <- "symptomatic"
      testing$sampling_pool_frac <- tp$symptomatic$pool_frac
      testing
    })

    budget_info <- shiny::reactive({
      fixed_params$budget
    })

    starter_intel <- shiny::reactive({
      fixed_params$starter_intel
    })

    output$admin_controls <- shiny::renderUI({
      if (!is_admin()) {
        return(NULL)
      }

      seed_selected <- seed_choice_from_value(shiny::isolate(shared_admin$seed_borough))
      scenario_selected <- shiny::isolate(shared_admin$scenario_id)
      if (is.null(scenario_selected) || is.na(scenario_selected) || scenario_selected == "") {
        scenario_selected <- "custom"
      }
      if (!(scenario_selected %in% scenario_defs$id)) {
        scenario_selected <- "custom"
      }

      shiny::tagList(
        shiny::hr(),
        shiny::tags$h5("Admin controls"),
        shiny::tags$p(
          class = "text-muted small",
          "Changes apply to all sessions on the next turn."
        ),
        shiny::selectInput(
          ns("admin_scenario"),
          label = "Scenario template",
          choices = scenario_labels,
          selected = scenario_selected
        ),
        shiny::uiOutput(ns("admin_scenario_note")),
        shiny::numericInput(
          ns("admin_rt"),
          label = "R0 (R if nobody were immune)",
          value = shiny::isolate(shared_admin$Rt),
          min = 0,
          step = 0.05
        ),
        shiny::numericInput(
          ns("admin_k"),
          label = "Overdispersion k",
          value = shiny::isolate(shared_admin$k),
          min = 0.01,
          step = 0.05
        ),
        shiny::numericInput(
          ns("admin_imports_prob"),
          label = "Imports probability",
          value = shiny::isolate(shared_admin$imports_prob),
          min = 0,
          max = 1,
          step = 0.01
        ),
        shiny::numericInput(
          ns("admin_lambda_import"),
          label = "Imports mean (lambda)",
          value = shiny::isolate(shared_admin$lambda_import),
          min = 0,
          step = 0.1
        ),
        shiny::selectInput(
          ns("admin_seed_borough"),
          label = "Initial seed borough",
          choices = seed_choices,
          selected = seed_selected
        ),
        shiny::numericInput(
          ns("admin_seed_cases"),
          label = "Initial seed cases",
          value = shiny::isolate(shared_admin$seed_cases),
          min = 0,
          step = 1
        ),
        shiny::numericInput(
          ns("admin_death_ifr"),
          label = "Death IFR",
          value = shiny::isolate(shared_admin$death_ifr),
          min = 0,
          max = 1,
          step = 0.001
        ),
        shiny::numericInput(
          ns("admin_death_delay"),
          label = "Death delay (turns)",
          value = shiny::isolate(shared_admin$death_delay),
          min = 0,
          step = 1
        ),
        shiny::actionButton(
          ns("admin_reset_all"),
          "Reset all sessions",
          class = "btn-outline-danger w-100"
        ),
        shiny::actionButton(
          ns("admin_reset_defaults"),
          "Reset to defaults",
          class = "btn-outline-secondary w-100 mt-2"
        )
      )
    })

    output$admin_scenario_note <- shiny::renderUI({
      if (!is_admin()) {
        return(NULL)
      }
      scenario_id <- input$admin_scenario
      if (is.null(scenario_id) || scenario_id == "" || is.na(scenario_id)) {
        scenario_id <- "custom"
      }
      scenario <- scenario_lookup(scenario_id, scenario_defs)
      objective <- scenario$objective[[1]]
      if (is.null(objective) || identical(objective, "")) {
        return(NULL)
      }
      shiny::tags$p(class = "text-muted small", objective)
    })

    observeEvent(
      list(
        input$admin_rt,
        input$admin_k,
        input$admin_imports_prob,
        input$admin_lambda_import,
        input$admin_seed_borough,
        input$admin_seed_cases,
        input$admin_death_ifr,
        input$admin_death_delay
      ),
      {
        shiny::req(is_admin())
        shiny::req(
          input$admin_rt,
          input$admin_k,
          input$admin_imports_prob,
          input$admin_lambda_import,
          input$admin_seed_borough,
          input$admin_seed_cases,
          input$admin_death_ifr,
          input$admin_death_delay
        )

        shared_admin$Rt <- max(0, input$admin_rt)
        shared_admin$k <- max(0.01, input$admin_k)
        shared_admin$imports_prob <- min(1, max(0, input$admin_imports_prob))
        shared_admin$lambda_import <- max(0, input$admin_lambda_import)

        seed_choice <- input$admin_seed_borough
        if (is.null(seed_choice) || seed_choice == "random" || seed_choice == "") {
          shared_admin$seed_borough <- NA_integer_
        } else {
          seed_value <- suppressWarnings(as.integer(seed_choice))
          if (is.na(seed_value)) {
            seed_value <- NA_integer_
          }
          shared_admin$seed_borough <- seed_value
        }

        seed_cases <- suppressWarnings(as.integer(round(input$admin_seed_cases)))
        if (is.na(seed_cases) || seed_cases < 0L) {
          seed_cases <- 0L
        }
        shared_admin$seed_cases <- seed_cases

        death_ifr <- suppressWarnings(as.numeric(input$admin_death_ifr))
        if (is.na(death_ifr) || !is.finite(death_ifr)) {
          death_ifr <- 0
        }
        shared_admin$death_ifr <- min(1, max(0, death_ifr))

        death_delay <- suppressWarnings(as.integer(round(input$admin_death_delay)))
        if (is.na(death_delay) || death_delay < 0L) {
          death_delay <- 0L
        }
        shared_admin$death_delay <- death_delay
      },
      ignoreInit = TRUE
    )

    observeEvent(input$admin_scenario, {
      shiny::req(is_admin())
      scenario_id <- input$admin_scenario
      if (is.null(scenario_id) || scenario_id == "" || is.na(scenario_id)) {
        scenario_id <- "custom"
      }
      if (identical(scenario_id, shiny::isolate(shared_admin$scenario_id))) {
        return()
      }
      apply_scenario_defaults(scenario_id)
    }, ignoreInit = TRUE)

    observeEvent(input$admin_reset_all, {
      shiny::req(is_admin())
      reset_signal(reset_signal() + 1L)
    })

    observeEvent(input$admin_reset_defaults, {
      shiny::req(is_admin())
      scenario_id <- input$admin_scenario
      if (is.null(scenario_id) || scenario_id == "" || is.na(scenario_id)) {
        scenario_id <- "custom"
      }
      apply_scenario_defaults(scenario_id)
    })

    reseed <- shiny::eventReactive(input$reseed, {
      if (isTRUE(input$random_seed)) {
        sample.int(1e6, 1)
      } else {
        input$rng_seed
      }
    }, ignoreNULL = FALSE)

    list(
      epidemiology = params_epidemic,
      mortality = params_mortality,
      testing = params_testing,
      budget = budget_info,
      starter_intel = starter_intel,
      end = shiny::reactive(input$end),
      reset = shiny::reactive(input$reset),
      reseed = reseed
    )
  })
}

# Surveillance module ----------------------------------------------------------
#
# Everything the response team can see: the latest report (with share
# positive, Rt and any warnings in it) and one chart of three signals over
# time (positive tests, hospital admissions, deaths). Only returned test
# results and public reports are used (never the hidden truth).

mod_dashboard_ui <- function(id) {
  ns <- shiny::NS(id)
  bslib::card(
    bslib::card_header("Surveillance"),
    bslib::card_body(
      class = "p-2",

      # the latest report, with any warnings (stays until the next one)
      shiny::div(
        class = "p-2 mb-2 rounded small",
        style = "background: var(--bs-tertiary-bg); border-left: 4px solid var(--bs-secondary-color);",
        shiny::htmlOutput(ns("turn_log"))
      ),

      # one chart: three signals on one log scale, so lines that run parallel
      # tell the same story and lines that pull apart disagree
      shiny::div(style = "height: 280px;", shiny::plotOutput(ns("signals_plot"), height = "100%")),
      shiny::div(class = "small text-muted", shiny::textOutput(ns("totals_text"), inline = TRUE))
    )
  )
}

mod_dashboard_server <- function(
    id,
    observed_history,
    queue_state,
    spend_info = shiny::reactive(NULL),
    available_now,
    reports,
    turn_log = shiny::reactive(character()),
    system_status = shiny::reactive(NULL),
    date_label = function(turn) turn,
    gens_per_turn = shiny::reactive(1),
    sentinel = shiny::reactive(NULL),
    dark_mode = shiny::reactive(FALSE),
    app_ready = shiny::reactive(TRUE)) {
  shiny::moduleServer(id, function(input, output, session) {
    ready <- shiny::reactive({
      isTRUE(app_ready())
    })

    # every signal per report (turn), every turn present -----------------------
    signals <- shiny::reactive({
      hist <- observed_history()
      rep <- reports()

      # test results taken on turn t come back with the report for turn t + 1,
      # alongside that report's hospital numbers, so they are plotted there
      # (plotting them at t left every chart ending on an empty report)
      last_turn <- max(c(0, hist$turn_available + 1, rep$turn))
      turns <- 0:last_turn
      confirmed <- numeric(length(turns))
      tests <- numeric(length(turns))
      suspected <- numeric(length(turns))
      deaths <- numeric(length(turns))

      if (!is.null(hist) && nrow(hist) > 0) {
        by_turn <- hist |>
          dplyr::group_by(turn_available) |>
          dplyr::summarise(positives = sum(positives), tests = sum(n), .groups = "drop")
        confirmed[by_turn$turn_available + 2] <- by_turn$positives
        tests[by_turn$turn_available + 2] <- by_turn$tests
      }
      if (!is.null(rep) && nrow(rep) > 0) {
        by_turn <- rep |>
          dplyr::group_by(turn) |>
          dplyr::summarise(admissions = sum(admissions), deaths = sum(deaths), .groups = "drop")
        suspected[by_turn$turn + 1] <- by_turn$admissions
        deaths[by_turn$turn + 1] <- by_turn$deaths
      }

      # the public health agency's steady sample: positives per report (its
      # sample on turn t comes back with the report for t + 1)
      agency <- numeric(length(turns))
      sen <- sentinel()
      if (!is.null(sen) && nrow(sen) > 0) {
        keep <- sen$turn + 2 <= length(turns)
        agency[sen$turn[keep] + 2] <- sen$positives[keep]
      }
      # Rt from hospital admissions: a fixed share of cases end up in hospital
      # whatever anyone's testing, so this is the steadiest signal (the
      # agency's small sample finds too few positives while it is rare).
      # Growth per report, turned into growth per generation (1 = flat).
      rt <- rep(NA_real_, length(turns))
      rt_tbl <- estimate_rt_table(suspected)
      if (nrow(rt_tbl) > 0) {
        rt[rt_tbl$t_end] <- rt_tbl$mean^(1 / gens_per_turn())
      }

      tibble::tibble(
        turn = turns,
        confirmed = confirmed,
        tests = tests,
        share_positive = ifelse(tests > 0, 100 * confirmed / tests, NA_real_),
        agency_positives = agency,
        suspected = suspected,
        deaths = deaths,
        rt = rt
      )
    })

    # latest value and change since the report before, e.g. "0.9% (+0.7)"
    with_change <- function(x, digits, suffix = "") {
      x <- x[!is.na(x)]
      if (length(x) == 0) return(NA_character_)
      txt <- paste0(formatC(utils::tail(x, 1), format = "f", digits = digits), suffix)
      if (length(x) >= 2) {
        d <- diff(utils::tail(x, 2))
        txt <- paste0(txt, " (", if (d >= 0) "+" else "", formatC(d, format = "f", digits = digits), ")")
      }
      txt
    }

    output$turn_log <- shiny::renderUI({
      req(ready())
      log <- turn_log()
      if (length(log) == 0) {
        return(shiny::HTML("Set your response, then press <b>Next report</b>."))
      }

      s <- signals()
      positive_txt <- with_change(s$share_positive, 1, "%")
      rt_txt <- with_change(s$rt, 2)
      sen <- sentinel()
      latest_agency <- if (!is.null(sen) && nrow(sen) > 0) sen[nrow(sen), ] else NULL

      shiny::tagList(
        shiny::tags$b(log[1]),
        lapply(log[-1], shiny::div),
        if (!is.na(positive_txt)) shiny::div(paste("Your tests: share positive", positive_txt)),
        if (!is.null(latest_agency)) shiny::div(sprintf("Agency: sample of %s with symptoms, %s positive.",
                                                       format(latest_agency$tests, big.mark = ","), latest_agency$positives)),
        # Rt stands out: the quickest read of where the outbreak is heading
        shiny::div(
          class = "mt-1",
          "Rt (from hospital admissions): ",
          shiny::span(class = "rt-value",
                      if (is.na(rt_txt)) "not yet clear" else rt_txt)
        ),
        lapply(warning_list(), function(w) {
          shiny::div(class = paste0("text-", w$level, " fw-semibold"), w$text)
        })
      )
    })

    # warnings -----------------------------------------------------------------

    warning_list <- shiny::reactive({
      req(ready())
      s <- signals()
      status <- system_status()
      n <- nrow(s)
      found <- list()

      add <- function(level, text) {
        found[[length(found) + 1]] <<- list(level = level, text = text)
      }

      # rising fast: up by half since the last report, from a meaningful base
      rising <- function(now, before, minimum) {
        !is.na(now) && !is.na(before) && now >= minimum && now >= 1.5 * max(before, 1)
      }

      if (!is.null(status)) {
        if (status$bed_pressure >= 1) {
          add("danger", "Hospitals are full: patients without a bed are dying.")
        } else if (status$bed_pressure >= 0.8) {
          add("danger", sprintf("Hospital beds %d%% full.", round(100 * status$bed_pressure)))
        } else if (status$bed_pressure >= 0.5) {
          add("warning", sprintf("Hospital beds over half full (%d%%).", round(100 * status$bed_pressure)))
        }
        if (status$lab_backlog > 0) {
          add("warning", "Labs are behind: PCR results are delayed.")
        }
        if (!is.null(status$pot_share) && status$pot_share < 0.1) {
          add("danger", "Budget almost spent.")
        } else if (!is.null(status$pot_share) && status$pot_share < 0.25) {
          add("warning", "Budget running low.")
        }
      }

      if (n >= 2) {
        now <- s[n, ]
        before <- s[n - 1, ]
        if (rising(now$confirmed, before$confirmed, 10)) {
          add("warning", "Positive tests rising fast.")
        }
        if (rising(now$suspected, before$suspected, 5)) {
          add("warning", "Admissions rising fast.")
        }
        if (now$deaths >= 3 && now$deaths > before$deaths) {
          add("danger", "Deaths rising.")
        }
        if (rising(now$share_positive, before$share_positive, 2)) {
          add("warning", "Share positive rising.")
        }
        if (!is.na(now$rt) && now$rt > 1 && !is.na(before$rt) && now$rt > before$rt) {
          add(if (now$rt > 1.5) "danger" else "warning", "Rt above 1 and rising.")
        }
      }

      found
    })

    # one chart of three signals ----------------------------------------------

    output$signals_plot <- shiny::renderPlot({
      req(ready())
      s <- signals()

      series <- c(
        confirmed = "positive tests",
        suspected = "hospital admissions",
        deaths = "deaths"
      )
      series_colours <- c(
        "positive tests" = "#4fc3f7",
        "hospital admissions" = "#f6d55c",
        "deaths" = "#e15759"
      )
      long <- dplyr::bind_rows(lapply(names(series), function(m) {
        tibble::tibble(turn = s$turn, value = s[[m]], series = series[[m]])
      }))
      long$series <- factor(long$series, levels = series)

      # latest value and change since the report before, at the end of each line
      ends <- long |>
        dplyr::group_by(series) |>
        dplyr::arrange(turn, .by_group = TRUE) |>
        dplyr::summarise(
          turn = dplyr::last(turn),
          value = dplyr::last(value),
          change = if (dplyr::n() >= 2) dplyr::last(value) - dplyr::nth(value, -2) else NA_real_,
          .groups = "drop"
        )
      ends$label <- sprintf(
        "%s %s%s",
        format(round(ends$value), big.mark = ","), ends$series,
        ifelse(is.na(ends$change), "", sprintf(" (%s%s)", ifelse(ends$change >= 0, "+", ""), format(round(ends$change), big.mark = ",")))
      )

      max_turn <- max(4, max(s$turn))
      col <- chart_colours(dark_mode())

      # log scale that still shows zero: 0, 1, 10, 100, ...
      log_breaks <- function(lim) {
        b <- c(0, 10^(0:8))
        b[b <= max(lim)]
      }

      ggplot2::ggplot(long, ggplot2::aes(x = turn, y = value, colour = series)) +
        ggplot2::geom_line(linewidth = 0.9) +
        ggplot2::geom_point(size = 1.4) +
        ggplot2::geom_text(
          data = ends, ggplot2::aes(label = label),
          hjust = -0.05, size = 3.2, fontface = "bold", show.legend = FALSE
        ) +
        ggplot2::scale_colour_manual(values = series_colours, guide = "none") +
        ggplot2::scale_x_continuous(
          limits = c(0, max_turn + 3.5),
          breaks = function(lim) {
            b <- scales::breaks_pretty(n = 5)(c(0, max_turn))
            b[b >= 0 & b <= max_turn & b == round(b)]
          },
          labels = date_label
        ) +
        ggplot2::scale_y_continuous(
          trans = scales::pseudo_log_trans(sigma = 1, base = 10),
          breaks = log_breaks,
          labels = scales::label_comma(),
          expand = ggplot2::expansion(mult = c(0.02, 0.1))
        ) +
        ggplot2::labs(
          x = NULL, y = NULL,
          title = "Each report (log scale: parallel lines are growing at the same rate)"
        ) +
        chart_theme(dark_mode(), base_size = 10) +
        ggplot2::theme(
          plot.title = ggplot2::element_text(size = 9, face = "plain", colour = col$muted),
          plot.margin = ggplot2::margin(2, 5, 2, 5)
        )
    }, bg = "transparent")

    output$totals_text <- shiny::renderText({
      req(ready())
      hist <- observed_history()
      rep <- reports()
      queue <- queue_state()
      total_pos <- if (is.null(hist) || nrow(hist) == 0) 0 else sum(hist$positives)
      total_tests <- if (is.null(hist) || nrow(hist) == 0) 0 else sum(hist$n)
      total_adm <- if (is.null(rep) || nrow(rep) == 0) 0 else sum(rep$admissions)
      total_deaths <- if (is.null(rep) || nrow(rep) == 0) 0 else sum(rep$deaths)
      waiting <- if (is.null(queue) || nrow(queue) == 0) 0 else sum(queue$n)
      paste0(
        "Totals so far: ", format(total_pos, big.mark = ","), " confirmed from ",
        format(total_tests, big.mark = ","), " tests · ",
        format(total_adm, big.mark = ","), " admissions · ",
        format(total_deaths, big.mark = ","), " deaths · ",
        format(waiting, big.mark = ","), " tests awaiting results"
      )
    })

    # share positive and Rt are shown in the top bar
    list(signals = signals)
  })
}

# Replay: what you saw, and what really happened ------------------------------
#
# After the response, the whole outbreak plays back on one clock, a week at a
# time, from the day the first person was infected:
#   left  - what the response team saw: nothing at all during the unseen
#           start, then their own map and report for each week
#   right - what really happened: new infections in each area, hidden until
#           the player presses Reveal
# so students can see, for example, that the main cluster was somewhere else
# all along.

# Everything shown for one week of the replay ----------------------------------
#
# step 0 is the week of the first infection; the first report is at step
# `truth_offset`. Returns what was seen (results back that week, that week's
# hospital and death reports, the report text) and what was true.
reveal_frame <- function(state, step, config, report_lines = list()) {
  offset <- state$truth_offset %||% 0L
  turn <- step - offset

  # what was true that week: new infections per area, and totals so far
  history <- state$truth$history
  infections <- history[[min(step + 1L, length(history))]]
  so_far <- Reduce(`+`, history[seq_len(min(step + 1L, length(history)))])
  deaths <- state$truth$death_history
  deaths_so_far <- sum(unlist(deaths[seq_len(min(step + 1L, length(deaths)))]))

  # what was seen: nothing before the first report; then test results that
  # came back with that week's report, and that week's hospital reports
  seen <- turn >= 0
  results <- NULL
  reports <- NULL
  lines <- character()
  if (seen) {
    obs <- state$obs$history
    results <- obs[obs$turn_available == turn - 1L, , drop = FALSE]
    reports <- state$reports[state$reports$turn == turn, , drop = FALSE]
    if (length(report_lines) >= turn + 1L) lines <- report_lines[[turn + 1L]]
  }

  list(
    step = step,
    turn = turn,
    date = turn_date(turn, config),
    seen = seen,
    results = results,
    reports = reports,
    report_lines = lines,
    infections = infections,
    infections_this_week = sum(infections),
    infections_so_far = sum(so_far),
    deaths_so_far = deaths_so_far
  )
}

