mod_reveal_server <- function(id, state, config, report_lines, boros, pop_tbl, true_start = shiny::reactive(NULL),
                              first_report = shiny::reactive(NULL)) {
  shiny::moduleServer(id, function(input, output, session) {
    ns <- session$ns
    revealed <- shiny::reactiveVal(FALSE)
    shiny::observeEvent(input$reveal, revealed(TRUE))

    # engine vectors are in the population table's order; the map has its own
    order_on_map <- match(boros$borough_name, pop_tbl$borough_name)
    to_map_index <- function(i) match(pop_tbl$borough_name[i], boros$borough_name)
    pop <- pop_tbl$pop[order_on_map]
    centroids <- sf::st_geometry(boros) |>
      sf::st_centroid(of_largest_polygon = TRUE) |>
      sf::st_coordinates()
    bbox <- sf::st_bbox(boros)

    base_map <- function() {
      leaflet::leaflet(boros, options = leaflet::leafletOptions(scrollWheelZoom = FALSE, zoomControl = FALSE)) |>
        leaflet::addPolygons(
          layerId = boros$borough_name, weight = 0.8, color = "#ffffff", opacity = 0.8,
          fillOpacity = 0.9, fillColor = "#3d4f61", label = ~borough_name, group = "areas"
        ) |>
        leaflet::fitBounds(bbox[["xmin"]], bbox[["ymin"]], bbox[["xmax"]], bbox[["ymax"]])
    }
    output$map_seen <- leaflet::renderLeaflet(base_map())
    output$map_true <- leaflet::renderLeaflet(base_map())

    # the clock: one step per week, from the first infection to the end
    n_steps <- shiny::reactive({
      s <- state()
      req(s)
      length(s$truth$history) - 1L
    })
    output$clock_ui <- shiny::renderUI({
      shiny::sliderInput(
        ns("step"), label = NULL, min = 0, max = n_steps(), value = 0, step = 1, ticks = FALSE,
        width = "100%",
        animate = shiny::animationOptions(interval = 900, loop = FALSE, playButton = "Play", pauseButton = "Pause")
      )
    })

    frame <- shiny::reactive({
      req(state(), !is.null(input$step))
      reveal_frame(state(), as.integer(input$step), config(), report_lines())
    })

    output$clock_label <- shiny::renderText({
      f <- frame()
      when <- if (f$turn < 0) {
        sprintf("%d week%s before the first report", -f$turn, if (f$turn == -1) "" else "s")
      } else if (f$turn == 0) {
        "first report"
      } else {
        sprintf("week %d of the response", f$turn)
      }
      paste0(format_date(f$date), " · ", when)
    })

    # left: what you saw ----------------------------------------------------------
    shiny::observe({
      f <- frame()
      layer_id <- input$seen_layer %||% "admissions"
      layers <- map_layers(f$results, f$reports, pop_tbl, boros$borough_name)
      layer <- layers[[layer_id]]
      fill <- if (f$seen) map_colours(layer$values, layer$breaks) else rep("#3d4f61", nrow(boros))

      proxy <- leaflet::leafletProxy(ns("map_seen"), data = boros) |>
        leaflet::clearGroup("areas") |>
        leaflet::addPolygons(
          layerId = boros$borough_name, weight = 0.8, color = "#ffffff", opacity = 0.8,
          fillOpacity = 0.9, fillColor = fill, label = boros$borough_name, group = "areas"
        ) |>
        leaflet::clearGroup("marks") |>
        leaflet::removeControl("seen_legend") |>
        leaflet::addLegend(
          layerId = "seen_legend", position = "bottomright", colors = c("#3d4f61", map_palette),
          labels = c(layer$none_label, layer$step_labels), title = layer$title, opacity = 0.9
        )

      first <- to_map_index(first_report())
      if (f$seen && length(first) == 1 && !is.na(first)) {
        proxy |> leaflet::addCircleMarkers(
          lng = centroids[first, 1], lat = centroids[first, 2], radius = 7, color = "#ffffff",
          weight = 2, fillColor = "#ff4d4d", fillOpacity = 1, label = "First report", group = "marks"
        )
      }
    })

    output$seen_text <- shiny::renderUI({
      f <- frame()
      if (!f$seen) {
        return(shiny::tags$em("Nothing reported yet: nobody knows this outbreak exists."))
      }
      shiny::tagList(lapply(f$report_lines, shiny::div))
    })

    # right: what really happened (hidden until Reveal) ------------------------------
    shiny::observe({
      f <- frame()
      shown <- revealed()
      infections <- f$infections[order_on_map]
      rate <- ifelse(infections > 0, 1e5 * infections / pop, NA_real_)
      breaks <- c(1, 3, 10, 30, 100, 300, 1000)
      fill <- if (shown) map_colours(rate, breaks) else rep("#2a3440", nrow(boros))

      proxy <- leaflet::leafletProxy(ns("map_true"), data = boros) |>
        leaflet::clearGroup("areas") |>
        leaflet::addPolygons(
          layerId = boros$borough_name, weight = 0.8, color = "#ffffff", opacity = if (shown) 0.8 else 0.3,
          fillOpacity = 0.9, fillColor = fill,
          label = if (shown) sprintf("%s: %s new infections", boros$borough_name, format(infections, big.mark = ",")) else NULL,
          group = "areas"
        ) |>
        leaflet::clearGroup("marks") |>
        leaflet::removeControl("true_legend")

      if (shown) {
        proxy <- proxy |> leaflet::addLegend(
          layerId = "true_legend", position = "bottomright", colors = c("#3d4f61", map_palette),
          labels = c("none", "under 1", "1 to 3", "3 to 10", "10 to 30", "30 to 100", "100 to 300", "300 to 1,000", "1,000 or more"),
          title = "New infections<br>per 100,000<br>(this week)", opacity = 0.9
        )
        start <- to_map_index(true_start())
        if (length(start) == 1 && !is.na(start)) {
          proxy |> leaflet::addCircleMarkers(
            lng = centroids[start, 1], lat = centroids[start, 2], radius = 7, color = "#ffffff",
            weight = 2, fillColor = "#000000", fillOpacity = 1, label = "Where it really began", group = "marks"
          )
        }
      }
    })

    output$true_text <- shiny::renderUI({
      f <- frame()
      if (!revealed()) {
        return(shiny::tags$em("Hidden. Play it through, then press Reveal to see what was really happening."))
      }
      shiny::tagList(
        shiny::div(sprintf("%s new infections this week", format(f$infections_this_week, big.mark = ","))),
        shiny::div(sprintf("%s infected so far, %s died so far",
                           format(f$infections_so_far, big.mark = ","), format(f$deaths_so_far, big.mark = ",")))
      )
    })
  })
}

# Truth engine ----------------------------------------------------------------

#' Initialise the hidden outbreak state
#'
#' @param n_boroughs Number of spatial units.
#' @param seed_boroughs Integer indices of boroughs that start with cases.
#' @param seed_cases Integer vector of cases corresponding to `seed_boroughs`.
#' @return A list describing the hidden epidemic state.
#' @export
init_truth <- function(n_boroughs, seed_boroughs = 1L, seed_cases = 10L) {
  if (length(n_boroughs) != 1L || !is.numeric(n_boroughs)) {
    stop("n_boroughs must be a single numeric value")
  }

  n_boroughs <- as.integer(n_boroughs)
  if (n_boroughs <= 0L) {
    stop("n_boroughs must be positive")
  }

  incidence <- integer(n_boroughs)

  if (length(seed_boroughs) != length(seed_cases)) {
    stop("seed_boroughs and seed_cases must have the same length")
  }

  if (length(seed_boroughs) > 0) {
    idx <- as.integer(seed_boroughs)
    if (any(idx < 1L | idx > n_boroughs)) {
      stop("seed_boroughs must fall within [1, n_boroughs]")
    }
    incidence[idx] <- incidence[idx] + as.integer(seed_cases)
  }

  deaths <- integer(n_boroughs)

  list(
    turn = 0L,
    incidence = incidence,
    cumulative = incidence,
    history = list(incidence),
    deaths = deaths,
    cumulative_deaths = deaths,
    death_history = list(deaths),
    death_queue = list()
  )
}

#' Advance the hidden outbreak by one turn
#'
#' @param state Current truth state as returned by `init_truth()` / `step_truth()`.
#' @param K Spatial kernel. Row j = where borough j's onward infections land;
#'   each row sums to 1, so every case causes Rt_global new cases on average.
#' @param Rt_global Effective reproduction number applied uniformly.
#' @param k_overdisp Negative binomial size parameter controlling overdispersion.
#' @param imports_prob Probability an import event occurs in each borough on a turn.
#' @param lambda_import Mean size of the Poisson import when it occurs.
#' @param isolated Per-borough number of (effectively) isolated cases that do
#'   not transmit this turn.
#' @param local_multiplier Per-borough multiplier on onward transmission from
#'   cases in that borough (local restrictions).
#' @param susceptible_frac Share of the population susceptible at the start
#'   (1 = nobody immune). Rt_global is the R in a fully susceptible population.
#' @param gens_per_step Generations of infection in one step (report interval
#'   in days / generation time in days). Each case's onward spread per step
#'   is (R per generation)^gens_per_step, so a weekly step keeps the same
#'   growth per day as stepping one generation at a time. 1 = one generation.
#' @return An updated state list with the next turn's incidence and cumulative totals.
#' @export
step_truth <- function(
    state,
    K,
    Rt_global,
    k_overdisp,
    imports_prob,
    lambda_import,
    pop = NULL,
    death_ifr = 0,
    death_delay = 0,
    isolated = 0,
    local_multiplier = 1,
    susceptible_frac = 1,
    gens_per_step = 1) {
  if (is.null(state) || !is.list(state)) {
    stop("state must be a list created by init_truth()")
  }

  I_t <- as.numeric(state$incidence)
  if (!is.matrix(K)) {
    stop("K must be a matrix")
  }

  if (ncol(K) != length(I_t)) {
    stop("Kernel dimension mismatch with incidence vector")
  }

  if (!is.numeric(Rt_global) || length(Rt_global) != 1L) {
    stop("Rt_global must be a single numeric value")
  }

  if (!is.numeric(k_overdisp) || length(k_overdisp) != 1L) {
    stop("k_overdisp must be a single numeric value")
  }

  if (k_overdisp <= 0 && !is.infinite(k_overdisp)) {
    stop("k_overdisp must be positive or Inf")
  }

  if (!is.numeric(imports_prob) || length(imports_prob) != 1L ||
      imports_prob < 0 || imports_prob > 1) {
    stop("imports_prob must be within [0, 1]")
  }

  if (!is.numeric(lambda_import) || length(lambda_import) != 1L ||
      lambda_import < 0) {
    stop("lambda_import must be non-negative")
  }

  if (!is.numeric(death_ifr) || length(death_ifr) != 1L || is.na(death_ifr) ||
      death_ifr < 0 || death_ifr > 1) {
    stop("death_ifr must be within [0, 1]")
  }

  if (!is.numeric(death_delay) || length(death_delay) != 1L || is.na(death_delay)) {
    stop("death_delay must be a single numeric value")
  }
  death_delay <- as.integer(round(death_delay))
  if (death_delay < 0L) {
    stop("death_delay must be non-negative")
  }

  # isolated cases (found by testing) do not pass the infection on, and
  # cases in boroughs under local restrictions pass it on less
  # (the per-generation multipliers compound over the generations in a step)
  g <- gens_per_step
  I_transmit <- pmax(I_t - isolated, 0) * local_multiplier^g

  # each borough's cases spread along its row of K:
  # mu[i] = Rt^g * sum_j K[j, i] * I_transmit[j]
  infectors <- as.numeric(crossprod(K, I_transmit))
  infectors[infectors < 0] <- 0
  mu <- infectors * Rt_global^g

  # Only susceptible people can be infected: the share still susceptible
  # starts at susceptible_frac (e.g. after vaccination) and falls as people
  # are infected. Effective R = Rt x share still susceptible.
  if (!is.null(pop)) {
    if (length(pop) != length(I_t)) {
      stop("Length of pop vector must match number of boroughs")
    }
    S_frac <- susceptible_frac - (state$cumulative / pop)
    S_frac[!is.finite(S_frac)] <- 0
    S_frac <- pmax(0, pmin(1, S_frac))
    mu <- mu * S_frac^g
  }

  # superspreading is per person: each infected person's onward infections
  # are NegBin(size = k), so the total from n people is NegBin(size = k * n).
  # (A single size = k for a whole area would make even a large outbreak
  # wobble and often vanish.)
  offspring <- if (is.infinite(k_overdisp)) {
    stats::rpois(length(mu), lambda = mu)
  } else {
    out <- integer(length(mu))
    live <- mu > 0
    out[live] <- stats::rnbinom(sum(live), size = k_overdisp * infectors[live], mu = mu[live])
    out
  }

  gates <- stats::rbinom(length(mu), size = 1L, prob = imports_prob)
  import_draws <- stats::rpois(length(mu), lambda = lambda_import)
  imports <- gates * import_draws

  I_next <- as.integer(offspring + imports)
  I_next[I_next < 0] <- 0L

  deaths_next <- integer(length(I_next))
  death_queue <- state$death_queue
  if (is.null(death_queue) || !is.list(death_queue)) {
    death_queue <- list()
  }

  if (death_delay <= 0L) {
    if (death_ifr > 0) {
      deaths_next <- stats::rbinom(length(I_next), size = I_next, prob = death_ifr)
    }
  } else {
    death_queue <- c(death_queue, list(I_next))
    if (length(death_queue) > death_delay) {
      exposed <- death_queue[[1]]
      death_queue <- death_queue[-1]
      if (length(exposed) == length(I_next) && death_ifr > 0) {
        deaths_next <- stats::rbinom(length(exposed), size = as.integer(exposed), prob = death_ifr)
      }
    }
  }

  cumulative <- state$cumulative + I_next
  history <- c(state$history, list(I_next))
  cumulative_deaths <- state$cumulative_deaths
  if (is.null(cumulative_deaths) || length(cumulative_deaths) != length(I_next)) {
    cumulative_deaths <- integer(length(I_next))
  }
  cumulative_deaths <- cumulative_deaths + as.integer(deaths_next)
  death_history <- state$death_history
  if (is.null(death_history) || !is.list(death_history)) {
    death_history <- list()
  }
  death_history <- c(death_history, list(as.integer(deaths_next)))

  list(
    turn = state$turn + 1L,
    incidence = I_next,
    cumulative = cumulative,
    history = history,
    last_mu = mu,
    last_imports = imports,
    deaths = as.integer(deaths_next),
    cumulative_deaths = cumulative_deaths,
    death_history = death_history,
    death_queue = death_queue
  )
}

# Starter intel helpers ------------------------------------------------------

starter_intel_allocations <- function(option = "none", truth_state, pop_tbl) {
  n_b <- length(truth_state$incidence)
  base <- tibble::tibble(
    borough_index = seq_len(n_b),
    borough_name = pop_tbl$borough_name,
    n_ag = integer(n_b),
    n_pcr = integer(n_b)
  )

  if (option == "none") {
    return(base)
  }

  if (option == "alert") {
    alert <- teaching_params()$starter_alert

    # the alert is only right some of the time; otherwise it is a false
    # alarm pointing at a borough picked at random
    alert_is_right <- stats::runif(1) < alert$accuracy
    hotspot <- which.max(truth_state$incidence)

    if (alert_is_right && truth_state$incidence[hotspot] > 0) {
      candidate <- hotspot
    } else {
      candidate <- sample.int(n_b, 1L)
    }

    base$n_ag[candidate] <- alert$tests
    return(base)
  }

  if (option == "sweep") {
    n_targets <- min(4L, n_b)
    positive_idx <- which(truth_state$incidence > 0)
    targets <- if (length(positive_idx) >= n_targets) {
      sample(positive_idx, n_targets)
    } else {
      sample(seq_len(n_b), n_targets)
    }
    base$n_ag[targets] <- 25L
    base$n_pcr[targets] <- 10L
    return(base)
  }

  base
}

starter_intel_label <- function(option) {
  switch(
    option,
    alert = "Starter intel: targeted alert",
    sweep = "Starter intel: wider screening",
    ""
  )
}

# Utility functions for loading static inputs -------------------------------

#' Load precomputed spatial inputs for the Outbreak London app
#'
#' @param data_dir Directory that contains the precomputed RDS files.
#' @param within_share Share of a case's onward infections that stay in its
#'   own borough (default kernel). The rest go to touching boroughs.
#' @param within_share_measles The same for the measles kernel (lower
#'   mobility, so more stays local).
#' @return A named list with sf objects, adjacency structures, kernel, and population table.
#' @export
load_inputs <- function(data_dir = "data", within_share = 0.7, within_share_measles = 0.8) {
  kernel_measles_path <- file.path(data_dir, "kernel_K_measles.rds")
  files <- list(
    boros = file.path(data_dir, "boroughs.rds"),
    boros_planar = file.path(data_dir, "boroughs_planar.rds"),
    nb = file.path(data_dir, "adjacency_nb.rds"),
    A = file.path(data_dir, "adjacency_matrix.rds"),
    K = file.path(data_dir, "kernel_K.rds"),
    pop_tbl = file.path(data_dir, "pop_boroughs.rds")
  )

  exists_mask <- vapply(files, file.exists, logical(1))
  if (!all(exists_mask)) {
    missing_files <- unlist(files[!exists_mask])
    stop(
      "Missing expected data files in ", data_dir, ": ",
      paste(basename(missing_files), collapse = ", ")
    )
  }

  inputs <- lapply(files, readRDS)

  boros <- inputs$boros
  if (!inherits(boros, "sf")) {
    stop("boroughs.rds must contain an sf object")
  }

  n_boroughs <- nrow(boros)
  if (n_boroughs != 33L) {
    stop("Expected 33 boroughs; found ", n_boroughs)
  }

  K <- inputs$K
  if (!is.matrix(K)) {
    stop("kernel_K.rds must be a matrix")
  }

  if (nrow(K) != ncol(K)) {
    stop("Spatial kernel must be square")
  }

  if (nrow(K) != n_boroughs) {
    stop("Spatial kernel dimension mismatch with borough count")
  }

  row_sums <- rowSums(K)
  if (any(!is.finite(row_sums))) {
    stop("Spatial kernel rows must have finite sums")
  }

  if (any(abs(row_sums - 1) > 1e-6)) {
    stop("Spatial kernel rows must sum to 1 within tolerance")
  }

  # Kernel convention: row j says where borough j's onward infections land,
  # and each row sums to 1, so every case causes Rt new cases wherever it is
  # (step_truth spreads with t(K) %*% I).
  #
  # kernel_K.rds holds only "spread evenly to touching boroughs" (A / degree,
  # no within-borough spread), so keep a share of each case's infections in
  # its own borough. These shares are guesses until a gravity kernel
  # replaces them.
  neighbour_spread <- K
  K <- within_share * diag(nrow(K)) + (1 - within_share) * neighbour_spread
  dimnames(K) <- dimnames(neighbour_spread)

  # The measles kernel is built the same way with more local spread.
  # (kernel_K_measles.rds is still checked below but no longer used.)
  K_measles_built <- within_share_measles * diag(nrow(K)) + (1 - within_share_measles) * neighbour_spread
  dimnames(K_measles_built) <- dimnames(neighbour_spread)

  K_measles <- NULL
  if (file.exists(kernel_measles_path)) {
    K_measles <- readRDS(kernel_measles_path)
    if (!is.matrix(K_measles)) {
      stop("kernel_K_measles.rds must be a matrix")
    }
    if (nrow(K_measles) != ncol(K_measles)) {
      stop("Measles kernel must be square")
    }
    if (nrow(K_measles) != nrow(K)) {
      stop("Measles kernel dimension mismatch with default kernel")
    }
    row_sums_measles <- rowSums(K_measles)
    if (any(!is.finite(row_sums_measles))) {
      stop("Measles kernel rows must have finite sums")
    }
    if (any(abs(row_sums_measles - 1) > 1e-6)) {
      stop("Measles kernel rows must sum to 1 within tolerance")
    }
  }
  K_measles <- K_measles_built

  pop_tbl <- inputs$pop_tbl
  if (!all(c("gss_code", "borough_name", "pop") %in% names(pop_tbl))) {
    stop("Population table must include gss_code, borough_name, pop")
  }

  if (any(is.na(pop_tbl$pop))) {
    stop("Population table contains missing population values")
  }

  if (nrow(pop_tbl) != n_boroughs) {
    stop("Population table row count must match borough count")
  }

  # Everything (K, A, populations, names) is indexed by position, in the
  # order of boroughs.rds. pop_boroughs.rds is stored alphabetically, so put
  # it in the map's order using the GSS code.
  pop_order <- match(boros$gss_code, pop_tbl$gss_code)
  if (any(is.na(pop_order))) {
    stop("Population table GSS codes do not match boroughs.rds")
  }
  pop_tbl <- pop_tbl[pop_order, , drop = FALSE]

  if (!all(pop_tbl$borough_name == boros$borough_name)) {
    stop("Borough names in the population table do not match boroughs.rds")
  }

  list(
    boros = boros,
    boros_planar = inputs$boros_planar,
    nb = inputs$nb,
    A = inputs$A,
    K = K,
    K_measles = K_measles,
    pop_tbl = pop_tbl
  )
}
